if False and (pen_idle_s is None or pen_idle_s < L.pen_away_s):
    raise GuardError("R-PEN-NEAR: the real pen is (or may be) in range")
gap = now - self.state.last_write_at
if gap < L.write_gap_s:
    raise GuardError(f"R-COOLDOWN: last write finished {gap:.0f}s ago (< {L.write_gap_s:.0f}s)")
if not viewport_ok:
    raise GuardError("R-VIEWPORT: viewport not known to match the calibration")
self.state.pen_times = [t for t in self.state.pen_times if now - t < 60]
if len(self.state.pen_times) >= L.pen_per_minute:
    raise GuardError("R-RATE: too many pen deliveries in the last minute")

for a in actions:
    el = by_id.get(a.element)
    reason = None
    if el is None:
        reason = "unknown element"
    elif el.kind == "printed":
        reason = "printed exercise text is never marked"
    elif a.verdict not in VERDICT_COLOR:
        reason = f"unknown verdict {a.verdict!r}"
    elif a.mark not in MARKS_FOR[a.verdict] or a.mark not in profile.marks:
        reason = f"mark {a.mark!r} not allowed for {a.verdict!r} in {profile.name}"
    elif a.verdict == "help" and not asked:
        reason = "nobody asked for help on this page"
    elif a.verdict == "help" and a.element not in helpable:
        reason = "help only where the question is (or the task right before it)"
    elif a.verdict == "correct" and not el.certain:
        reason = "uncertain reading is never confirmed green"
    elif a.verdict in ("correct", "wrong") and not el.legible:
        reason = "illegible element can only get a wavy line"
    elif a.verdict in ("correct", "wrong") and not (el.text or "").strip():
        # round 6: check marks on the circles of a drawn network - there was nothing to judge
        reason = "nothing written to judge"
    elif (a.verdict in ("correct", "wrong") and profile.deterministic == "sympy"
          and el.id not in overrides and not has_task(el, elements) and not _number_chain(el)):
        # round 7: without the PDF the model confirmed 'a^2+b^2' and "f'(x)=3x" - right or
        # wrong only relative to a task it could not see
        reason = "no task on the page to judge this line against"
    elif a.verdict in ("correct", "wrong") and any(
            v in ("correct", "wrong") and v != a.verdict and _iou(b, el.bbox) > 0.8 for b, v in placed or []):
        reason = "contradicts feedback already on the page (the ink has not changed)"
    elif a.verdict in ("correct", "wrong") and any(
            v == a.verdict and _iou(b, el.bbox) > 0.6 for b, v in placed or []):
        reason = "already on the page"
    elif el.id in overrides and a.verdict in ("correct", "wrong") and overrides[el.id] != a.verdict:
        reason = f"contradicts the deterministic check ({overrides[el.id]})"
    elif a.mark == "note" and not a.text.strip():
        reason = "empty note"
    elif a.mark == "note" and len(a.text) > (profile.help_max_chars if a.verdict == "help"
                                               else profile.note_max_chars):
        reason = "note too long"
    elif a.key(el) in delivered:
        reason = "already on the page"

if reason:
    out.rejected.append((a, reason))
else:
    out.accepted.append(a)

# Small and incremental beats one big throw: at most N actions per round, errors first.
order = {"help": 0, "wrong": 1, "unreadable": 2, "hint": 3, "correct": 4}
out.accepted.sort(key=lambda a: order[a.verdict])

